import{_ as a,c as e,o as i,a2 as r}from"./chunks/framework.CzULAunO.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/general-skills/computer-basic/1111.md","filePath":"docs/general-skills/computer-basic/1111.md","lastUpdated":1766652908000}'),t={name:"docs/general-skills/computer-basic/1111.md"};function o(s,l,n,c,d,h){return i(),e("div",null,l[0]||(l[0]=[r('<h2 id="数据备份与安全" tabindex="-1">数据备份与安全 <a class="header-anchor" href="#数据备份与安全" aria-label="Permalink to &quot;数据备份与安全&quot;">​</a></h2><p>&quot;鸡蛋🥚不能放在一个篮子里&quot;，需要对个人的重要数据进行备份，有无数的可能导致你的数据丢失：</p><p><strong>软件原因：</strong></p><ul><li>误删</li><li>被安全系统删除</li><li>被微软吃掉了</li><li>被<a href="https://mzh.moegirl.org.cn/%E5%9B%A0%E5%B9%A1%E5%B7%A1#%E7%9B%B8%E5%85%B3" target="_blank" rel="noreferrer">Ciallo～(∠·ω&lt; )⌒★</a>掉了</li></ul><p><strong>硬件原因：</strong></p><ul><li>洗衣机意外</li><li>丢失</li><li>芯片断裂</li><li>等等</li></ul><h2 id="备份策略建议" tabindex="-1">备份策略建议 <a class="header-anchor" href="#备份策略建议" aria-label="Permalink to &quot;备份策略建议&quot;">​</a></h2><h3 id="_3-2-1-备份策略" tabindex="-1">3-2-1 备份策略 <a class="header-anchor" href="#_3-2-1-备份策略" aria-label="Permalink to &quot;3-2-1 备份策略&quot;">​</a></h3><ul><li><strong>3</strong> 份副本：至少保留 3 份数据副本</li><li><strong>2</strong> 种介质：使用至少 2 种不同的存储介质</li><li><strong>1</strong> 份异地：至少 1 份备份存储在异地</li></ul><h3 id="推荐的备份工具" tabindex="-1">推荐的备份工具 <a class="header-anchor" href="#推荐的备份工具" aria-label="Permalink to &quot;推荐的备份工具&quot;">​</a></h3><ul><li><strong>云存储</strong>：OneDrive、Google Drive、百度网盘等</li><li><strong>本地备份</strong>：移动硬盘、U 盘</li><li><strong>专业备份软件</strong>：TimeShift（Linux）、Windows 备份和还原等</li></ul><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>定期检查备份完整性</li><li>重要文件多重备份</li><li>测试恢复流程</li></ul>',13)]))}const g=a(t,[["render",o]]);export{_ as __pageData,g as default};
